import{at as e,it as t,n,vt as r}from"./chunks/framework.B0lbOe_c.js";var i=JSON.parse(`{"title":"Diagramme","description":"","frontmatter":{"title":"Diagramme","covers":{"screens":["SCR-021","SCR-067"],"stories":["US-074"]}},"headers":[],"relativePath":"de/usage/diagrams.md","filePath":"de/usage/diagrams.md"}`),a={name:`de/usage/diagrams.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="diagramme" tabindex="-1">Diagramme <a class="header-anchor" href="#diagramme" aria-label="Permalink to “Diagramme”">​</a></h1><p>Ein Diagramm modelliert einen Geschäftsprozess oder eine andere Sicht auf die Architektur mit der Notation eines <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>, zum Beispiel <em>Process Model (BPMN 2.0)</em>. Du legst Diagramme als Objekte an, findest, benennst um, löschst und stellst sie wieder her, und du platzierst die Elemente des Viewpoints auf der Zeichenfläche eines Diagramms.</p><p>Zum Ansehen brauchst du die Berechtigung <code>entity:read</code> (zum Beispiel die Rolle <code>viewer</code>). Anlegen, Umbenennen und Löschen braucht <code>entity:write</code>, Wiederherstellen <code>entity:restore</code> (Rolle <code>enterprise-architect</code>). Service-Accounts mit <code>entity:write</code> können Diagramme über die API wie Personen anlegen und ändern.</p><h2 id="diagramme-finden" tabindex="-1">Diagramme finden <a class="header-anchor" href="#diagramme-finden" aria-label="Permalink to “Diagramme finden”">​</a></h2><p>Du findest Diagramme an drei Stellen:</p><ul><li><strong>Die Seite <em>Diagramme</em>:</strong> Wähle in der Kopfzeile <em>Diagramme</em>. Die Seite listet die Diagramme nach Namen, unabhängig von Gross- und Kleinschreibung, jeweils mit ihrem Viewpoint, der Notation des Viewpoints und dem Zeitpunkt der letzten Änderung. Gib einen Namensteil in <em>Nach Name filtern</em> ein, um die Liste einzugrenzen; Zeichen wie <code>%</code> und <code>_</code> gelten, wie eingegeben. Die Liste zeigt 50 Diagramme auf einmal; wähle <em>Mehr laden</em> für die nächsten. Ohne Diagramm meldet die Seite <em>Noch keine Diagramme.</em></li><li><strong>Der Browser:</strong> Die Kategorie <em>Diagramme</em> unter <em>Aktueller Stand</em> in der Seitenleiste listet die Diagramme mit der Notation als kleiner Markierung (siehe <a href="./navigation#browser">Navigationsbaum</a>).</li><li><strong>Der Navigationsbaum:</strong> Diagramme, die in einen Ordner eingeordnet wurden (siehe <a href="./navigation#place-a-diagram">Diagramm einordnen</a>).</li></ul><p>Wähle ein Diagramm, um seine Seite zu öffnen.</p><h2 id="diagramm-anlegen" tabindex="-1">Diagramm anlegen <a class="header-anchor" href="#diagramm-anlegen" aria-label="Permalink to “Diagramm anlegen”">​</a></h2><ol><li><p>Wähle auf der Seite <em>Diagramme</em> <em>Diagramm anlegen</em>.</p></li><li><p>Fülle den Dialog aus:</p><table tabindex="0"><thead><tr><th>Feld</th><th>Bedeutung</th></tr></thead><tbody><tr><td>Name</td><td>erforderlich, 1 bis 200 Zeichen; eindeutig unter den Diagrammen, unabhängig von Gross- und Kleinschreibung; umgebende Leerzeichen werden entfernt</td></tr><tr><td>Beschreibung</td><td>optional, bis zu 2000 Zeichen</td></tr><tr><td>Viewpoint</td><td>erforderlich; der Viewpoint des Diagramms und seine Notation</td></tr></tbody></table></li><li><p>Wähle <em>Anlegen</em>. Das neue, leere Diagramm öffnet sich.</p></li></ol><p>Den Viewpoint kannst du später ändern (siehe <a href="#change-the-viewpoint">Viewpoint ändern</a>). Ist der Name vergeben, meldet der Dialog <em>Ein Diagramm mit diesem Namen gibt es schon.</em></p><h2 id="the-canvas" tabindex="-1">Die Zeichenfläche <a class="header-anchor" href="#the-canvas" aria-label="Permalink to “Die Zeichenfläche”">​</a></h2><p>Die Seite eines Diagramms zeigt Name, Beschreibung und Viewpoint und darunter die Zeichenfläche mit den Formen des Diagramms. Jede Form ist ein Kasten mit dem Namen der Entität, der Abkürzung ihres Typs und, falls der Viewpoint eine vorgibt, einem Rand in der Farbe ihres Typs. <strong>Eine Form ist eine Ansicht einer Entität: Die Entität selbst bleibt im Repository.</strong> Dieselbe Entität darf in einem Diagramm mehrfach vorkommen. Ein Diagramm zeigt nur Entitäten der Typen, die sein Viewpoint erlaubt. Verbindungen werden als Kanten zwischen den Formen gezeichnet (siehe <a href="#connections">Verbindungen</a>). Notationsspezifische Formen, zum Beispiel die von BPMN, folgen in einer späteren Version; bis dahin ist jede Form ein Kasten.</p><p>Verschiebe die Zeichenfläche, indem du den Hintergrund ziehst, und zoome mit dem Mausrad oder mit den Schaltflächen <em>Vergrößern</em>, <em>Verkleinern</em> und <em>Ansicht einpassen</em> über der Zeichenfläche. Mit der Berechtigung <code>entity:read</code> kannst du das Diagramm so ansehen; die Zeichenfläche ist dann mit <em>Nur lesen</em> markiert und hat keine Palette, kein <em>Vorhandene hinzufügen</em> und kein <em>Speichern</em>.</p><p>Mit der Berechtigung <code>entity:write</code> bearbeitest du auch das Layout:</p><ul><li><strong>Neue Entität platzieren:</strong> Die Palette über der Zeichenfläche listet die Entitätstypen, die der Viewpoint erlaubt. Klicke einen Typ an, um eine neue Form in der Mitte der sichtbaren Zeichenfläche zu platzieren, oder ziehe den Typ auf die Zeichenfläche. Tippe den Namen in die neue Form und drücke Enter. Ohne Namen verschwindet die Form wieder (auch mit Escape). Die Form erhält die Standardgröße ihres Typs im Viewpoint in Punkt (pt); ohne gespeicherte Größe sind das 90 × 30 pt.</li><li><strong>Vorhandene Entität platzieren:</strong> <em>Vorhandene hinzufügen</em> öffnet eine Suche. Tippe einen Teil des Namens ein (ohne Unterscheidung von Groß- und Kleinschreibung; Zeichen wie <code>%</code> und <code>_</code> gelten, wie getippt) und wähle die Entität; <em>Mehr laden</em> zeigt weitere Treffer. Die Suche findet nur Entitäten der Typen, die der Viewpoint erlaubt. Die neue Form erscheint in der Mitte der sichtbaren Zeichenfläche.</li><li><strong>Verschieben und Größe ändern:</strong> Ziehe eine Form, und ziehe die Anfasser einer ausgewählten Form, um ihre Größe zu ändern. Mit der Tastatur wählst du eine Form (Tab oder Klick) und verschiebst sie mit den Pfeiltasten um 1 pt, mit Umschalt um 10 pt. Positionen liegen innerhalb von ±100 000 pt, Größen zwischen 1 und 10 000 pt, jeweils mit höchstens zwei Nachkommastellen. Eine Form in einem Container folgt ihm, wenn du den Container verschiebst (siehe <a href="#nested-shapes">Verschachtelte Formen</a>).</li><li><strong>Aus Diagramm entfernen:</strong> Wähle eine Form und dann <em>Aus Diagramm entfernen</em> über der Zeichenfläche, drücke Entf oder öffne mit der rechten Maustaste das Kontextmenü der Form. Die Form verschwindet aus dem Diagramm; <strong>die Entität bleibt im Repository.</strong></li><li><strong>Aus Repository löschen:</strong> Mit <code>entity:delete</code> wählst du <em>Aus Repository löschen</em> im Kontextmenü einer Form oder Kante, oder du drückst Strg+Entf auf der gewählten. Der Dialog nennt, was das Löschen mitnimmt: die Kinder der Entität auf allen Ebenen, die Verbindungen der Entität und ihrer Kinder und die aktiven Lösungen, die Änderungen daran haben. Nach deiner Bestätigung werden die Entität und alles, was mit ihr gelöscht wird, sofort gelöscht, <strong>ohne das ausdrückliche Speichern</strong>, und ihre Formen und Kanten verschwinden von der Zeichenfläche; deine übrigen ungespeicherten Änderungen bleiben. Andere Diagramme blenden die Formen aus, solange die Entität gelöscht ist, und zeigen sie wieder, wenn sie wiederhergestellt wurde (braucht <code>entity:restore</code>; siehe <a href="./deleted-entities">Gelöschte Entitäten</a>). Hat jemand die Entität geändert, nachdem du den Dialog geöffnet hast, sagt OEA das und bietet <em>Neu lesen</em> an. Eine Entität mit offenen Punkten einer Lösung kann nicht gelöscht werden; eine Gliederungshilfe und eine automatische Kompositionsverbindung werden so nicht gelöscht. Änderungen aktiver Lösungen an einer gelöschten Entität werden zu <a href="./solutions#go-live">Konflikten</a>, die die Lösung vor ihrem Go-live auflöst. Die externe ID einer gelöschten Entität bleibt reserviert.</li><li><strong>Details einer Entität:</strong> Wähle eine Form, um ihre Details neben der Zeichenfläche zu öffnen (siehe <a href="#details-of-an-entity">Details einer Entität</a>).</li><li><strong>Speichern:</strong> <em>Speichern</em> sichert alle Änderungen in einem Schritt, auch die Änderungen von Entitäten in den Details und die Kanten (siehe <a href="#connections">Verbindungen</a>). Bis dahin zeigt die Zeichenfläche <em>Ungespeicherte Änderungen</em>, und neue oder geänderte Formen tragen einen kleinen Punkt. Ein Diagramm enthält höchstens 2000 Formen, und ein Speichern legt höchstens 500 neue Entitäten an; die Zeichenfläche meldet, wenn eine Grenze erreicht ist.</li></ul><p>Verlässt du die Seite mit ungespeicherten Änderungen, fragt OEA, ob sie verworfen werden sollen. Hat jemand anderes (oder du in einem anderen Fenster) das Diagramm geändert, seit du es geöffnet hast, antwortet <em>Speichern</em> mit <em>Jemand anderes hat das Diagramm geändert</em>; wähle <em>Neu laden und meine Änderungen verwerfen</em>, um mit dem aktuellen Stand weiterzuarbeiten, oder <em>Weiter bearbeiten</em>, um deine Arbeit zuvor anderswo zu sichern. Auch das Umbenennen des Diagramms zählt als Änderung.</p><p>Lässt sich eine Form nicht speichern, zum Beispiel weil ihre Entität inzwischen gelöscht wurde, markiert die Zeichenfläche die Form mit dem Grund und behält alle deine Änderungen; gespeichert wird erst, wenn jede Form gültig ist. Eine Form, deren Typ der Viewpoint nicht erlaubt, ist ein <em>Konflikt</em> und folgt eigenen Regeln (siehe <a href="#change-the-viewpoint">Viewpoint ändern</a>).</p><h3 id="entitaten-mit-fehlenden-werten" tabindex="-1">Entitäten mit fehlenden Werten <a class="header-anchor" href="#entitaten-mit-fehlenden-werten" aria-label="Permalink to “Entitäten mit fehlenden Werten”">​</a></h3><p>Eine neue Entität von der Zeichenfläche hat nur einen Namen und einen Typ. Hat ihr Typ eine Pflichteigenschaft ohne Standardwert, wird die Entität trotzdem angelegt und gilt als <strong>unvollständig</strong>, bis der Wert geschrieben ist. Jede Form einer unvollständigen Entität zeigt <em>Unvollständig:</em> mit den Namen der fehlenden Eigenschaften. Andere Änderungen der Entität, zum Beispiel über die Batch-API, verlangen die Pflichtwerte weiterhin. Du vervollständigst die Entität in ihren Details (siehe unten) oder schreibst die Werte über die API (siehe <a href="./../api/">API-Referenz</a>).</p><p>Wird eine Entität gelöscht, sind ihre Formen im Diagramm ausgeblendet; sie erscheinen wieder, wenn die Entität wiederhergestellt wird.</p><h2 id="nested-shapes" tabindex="-1">Verschachtelte Formen <a class="header-anchor" href="#nested-shapes" aria-label="Permalink to “Verschachtelte Formen”">​</a></h2><p>Die Hierarchie der Entitäten (siehe <a href="./navigation#arrange-components">Komponenten anordnen</a>) lässt sich auf der Zeichenfläche zeigen: Eine Form kann in einer anderen Form desselben Diagramms liegen, ihrem <strong>Container</strong>, wie eine Komposition in ArchiMate. Ein Container ist eine Form, die andere Formen enthält; er trägt seinen Namen über ihnen und wächst, wenn du eine Form über seinen Rand hinaus verschiebst. Er schrumpft nie unter die Formen, die er enthält, und eine Form liegt vollständig in ihrem Container, höchstens 10 Ebenen tief. <strong>Das Verschachteln allein ändert nichts im Repository</strong>; ob sich die Eltern einer Entität ändern, wird getrennt gefragt (siehe unten).</p><ul><li><strong>Kinder anzeigen:</strong> Wenn du mit <em>Vorhandene hinzufügen</em> eine Entität platzierst, die Kinder hat, fragt OEA <em>Kinder anzeigen?</em>. Mit <em>Kinder anzeigen</em> werden die direkten Kinder, deren Typ der Viewpoint erlaubt und die das Diagramm noch nicht zeigt, in einem Raster in der neuen Form verschachtelt, und die Form wächst, um sie aufzunehmen. Ein Hinweis nennt die Kinder eines Typs, den der Viewpoint nicht erlaubt und die nicht platziert werden, und sagt, wenn nur die ersten 500 Kinder berücksichtigt wurden. Mit <em>Nur diese Entität</em> oder beim Schließen des Dialogs wird nur die Entität platziert. Es werden nur die direkten Kinder gezeigt, nicht deren Kinder; ein Kind, das selbst Kinder hat, bietet <em>Kinder anzeigen</em> selbst an.</li><li><strong>Später anzeigen:</strong> <em>Kinder anzeigen</em> im Kontextmenü einer Form macht dasselbe für eine bereits platzierte Form; Kinder, die das Diagramm schon zeigt, werden nicht noch einmal platziert.</li><li><strong>Ein Kind, das an anderer Stelle gezeigt wird:</strong> Es wird nicht ein zweites Mal verschachtelt. Ist seine automatische Kompositionsverbindung zu den Eltern im Viewpoint erlaubt, wird diese Verbindung als Kante gezeichnet. Sonst läuft eine <strong>Hierarchielinie</strong> vom Container zur Form des Kindes: eine gestrichelte Linie ohne Pfeilspitze. Wähle sie mit Tab oder per Klick aus und entferne sie mit <em>Aus Diagramm entfernen</em> oder Entf; die Hierarchie bleibt, wie sie ist. Die Linie wird nur gezeigt, solange die Entität des Kindes ein Kind der Entität des Containers ist.</li><li><strong>Eine Form in einen Container oder aus ihm heraus verschieben:</strong> Ziehe sie so, dass ihre Mitte in der anderen Form liegt, oder aus ihrem Container heraus. Die Form wird verschachtelt, der Container wächst, um sie aufzunehmen, und wenn die Einstellung fragt (siehe unten) und die Entität andere Eltern hat, fragt OEA <em>Neue Eltern?</em>. <em>Ja</em> ändert die Eltern der Entität mit dem nächsten Speichern, mit den Regeln des <a href="./navigation#arrange-components">Anordnens von Komponenten</a>: Ein Zyklus oder mehr als 10 Ebenen werden abgelehnt, eine Entität mit offenen Problemen einer Lösung kann keine neuen Eltern bekommen, und die Entität erhält eine neue Version. Beim Verlassen eines Containers wird gefragt, ob die Entität keine Eltern mehr hat. <em>Nein</em> ändert nur das Bild. OEA fragt nichts, wenn die Entität diese Eltern schon hat, wenn du eine Form innerhalb ihres Containers verschiebst und wenn die Einstellung nicht fragt.</li><li><strong>Ein neues Element in einem Container:</strong> Ein neues Element, das du aus der Palette auf einen Container ziehst, wird darin verschachtelt und <strong>als Kind der Entität des Containers</strong> angelegt, ohne Rückfrage. Auf einen neuen Container abgelegt, wird es Kind der neuen Entität; beide werden mit einem Speichern angelegt.</li><li><strong>Einen Container entfernen:</strong> <em>Aus Diagramm entfernen</em> bei einer Form, die andere Formen enthält, fragt nach einer Bestätigung, die die Zahl der verschachtelten Formen nennt: Sie verlassen mit dem Container das Diagramm, ebenso ihre Kanten und Linien. <strong>Die Entitäten bleiben im Repository.</strong></li></ul><p>Die Einstellung, ob OEA <em>Neue Eltern?</em> fragt, gilt für die ganze Instanz und lässt sich je Viewpoint überschreiben (siehe <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>). Hat jemand anderes eine Entität geändert, deren Eltern du geändert hast, nennt <em>Speichern</em> sie und bietet <em>Neu laden</em> an, wie bei anderen Änderungen von Entitäten; das Neuladen verwirft deine Änderung ihrer Eltern. Ein Container, dessen Entität gelöscht ist, wird ausgeblendet; die darin verschachtelten Formen bleiben an ihren Positionen und werden ohne Container gezeigt. Kehrt der Container zurück, kehren die Formen, die inzwischen gespeichert wurden, nicht in ihn zurück.</p><h2 id="details-of-an-entity" tabindex="-1">Details einer Entität <a class="header-anchor" href="#details-of-an-entity" aria-label="Permalink to “Details einer Entität”">​</a></h2><p>Wähle eine Form, um das Detailfenster ihrer Entität neben der Zeichenfläche zu öffnen. Es zeigt Namen, Beschreibung, Typ und Version der Entität und für jede Eigenschaft ihres Typs ein Feld, in der Reihenfolge des Typs; eine Pflichteigenschaft ist markiert. Schließe das Fenster mit der Schaltfläche zum Schließen oder mit Escape; mit Tab gelangst du von der gewählten Form in das Fenster.</p><ul><li><strong>Lesen:</strong> Jede Person mit <code>entity:read</code> sieht die Werte. Einen Wert, den du nicht lesen darfst, zum Beispiel einen, der auf eine Rolle beschränkt ist, zeigt das Fenster als <em>Eingeschränkt</em>. Ohne <code>entity:write</code> ist das Fenster nur lesbar.</li><li><strong>Ändern:</strong> Mit <code>entity:write</code> änderst du den Namen, die Beschreibung und die Werte der Eigenschaften, die du schreiben darfst. Eine Eigenschaft, die auf eine Rolle beschränkt ist, die du nicht hast, zeigt ihren Wert ohne Eingabefeld. Bei einer Referenzeigenschaft suchst du die Entitäten des referenzierten Typs nach Namen. Eine leere Eingabe entfernt den Wert.</li><li><strong>Unvollständige Entität vervollständigen:</strong> Das Fenster nennt die fehlenden Pflichtwerte (<em>Pflichtwerte fehlen: …</em>). Trage sie ein und wähle <em>Speichern</em>; die Form verliert dann die Markierung <em>Unvollständig:</em>. Eine Pflichteigenschaft, die du nicht ändern darfst, bleibt Pflicht; die Entität bleibt unvollständig, bis jemand mit Schreibrecht sie schreibt.</li><li><strong>Speichern:</strong> Deine Änderungen in den Details zählen als ungespeicherte Änderungen des Diagramms, mit der Markierung <em>Ungespeicherte Änderungen</em>, und werden mit dem Layout durch <em>Speichern</em> in einem Schritt gesichert: Entweder wird alles gespeichert oder nichts. Ein Speichern ändert höchstens 500 Entitäten; die Zeichenfläche meldet, wenn die Grenze erreicht ist. Wer eine noch unvollständige Entität ändert, braucht ihre Pflichtwerte; vervollständige sie also im selben Schritt.</li><li><strong>Neue Entität:</strong> Auch die Details einer neuen Form nehmen eine Beschreibung und Werte auf; sie werden mit der Entität angelegt.</li></ul><p>Hat jemand anderes eine Entität geändert, seit du ihre Details geöffnet hast, antwortet <em>Speichern</em> mit <em>… wurde zwischenzeitlich von jemand anderem geändert</em> unter Nennung der Entität und speichert nichts. Deine Änderungen bleiben auf der Zeichenfläche; wähle <em>… neu laden und meine Änderungen daran verwerfen</em>, um die Entität erneut zu lesen (das verwirft nur deine Änderungen an dieser Entität), wiederhole dann deine Änderung und speichere erneut. Eine Entität mit offenen Punkten einer Lösung lässt sich nicht ändern; die Meldung nennt die Entität und ihre offenen Punkte, und deine Änderungen bleiben. Einen Wert, den der Server ablehnt, markiert das Fenster am Feld mit dem Grund.</p><h2 id="connections" tabindex="-1">Verbindungen <a class="header-anchor" href="#connections" aria-label="Permalink to “Verbindungen”">​</a></h2><p>Eine Verbindung ist eine eigene Entität: Sie verbindet eine Quell- mit einer Zielentität und hat einen Typ, einen Namen und Werte. Ein Diagramm zeigt eine Verbindung als <strong>Kante</strong>, eine gerade Linie zwischen zwei Formen mit einem Pfeil am Ziel, dem Namen der Verbindung und, wenn du welche setzt, Knickpunkten. Die Linie verläuft von einer Form der Quelle der Verbindung zu einer Form ihres Ziels, die Richtung folgt also der Verbindung. <strong>Eine Kante ist eine Ansicht einer Verbindung: Die Verbindung selbst bleibt im Repository.</strong> Dieselbe Verbindung darf in einem Diagramm mehrere Kanten haben, und nicht jede Verbindung zwischen zwei Formen muss gezeigt werden.</p><ul><li><strong>Verbindung zeichnen:</strong> Ziehe mit <code>entity:write</code> von einem Anfasser an der linken oder rechten Seite einer Form auf eine andere Form. OEA bietet die Verbindungstypen an, die der Viewpoint und das Metamodell zwischen den beiden Typen erlauben. Bei einem Typ wird er verwendet, bei mehreren wählst du einen aus, bei keinem meldet die Zeichenfläche <em>Hier ist keine Verbindung erlaubt.</em> Ein Typ, der nur von der zweiten zur ersten Form erlaubt ist, wird von der zweiten Form aus gezeichnet. Die Verbindung wird mit <em>Speichern</em> angelegt, im selben Schritt wie das Layout, und nach ihren Enden benannt (<em>Quelle → Ziel</em>). Hat ihr Typ eine Pflichteigenschaft ohne Standardwert, wird die Verbindung trotzdem angelegt und gilt als <strong>unvollständig</strong>, bis der Wert geschrieben ist; die Kante zeigt <em>Unvollständig:</em> mit den Namen. Eine Verbindung eines Typs, der die Sichtbarkeit von Eigenschaften steuert (ein <em>Scoping-Verbindungstyp</em>), braucht zusätzlich die Berechtigung <code>visibility-scope:assign</code>; ohne sie meldet <em>Speichern</em>, dass du Verbindungen dieses Typs nicht anlegen darfst.</li><li><strong>Vorhandene Verbindungen anzeigen:</strong> Ein Diagramm zeigt die vorhandenen Verbindungen einer Entität nicht von selbst. Platzierst du eine vorhandene Entität mit <em>Vorhandene hinzufügen</em> und hat sie Verbindungen zu Entitäten, die schon auf der Zeichenfläche sind, meldet ein Hinweis <em>N Verbindungen verfügbar</em>. Wähle <em>Alle anzeigen</em>, um ihre Kanten hinzuzufügen, <em>Auswählen…</em>, um einige zu wählen, oder <em>Verwerfen</em>; ohne deine Wahl wird nichts hinzugefügt. Angeboten werden nur Verbindungen von Typen, die der Viewpoint erlaubt, keine gelöschten.</li><li><strong>Verbundenes Element hinzufügen:</strong> Wähle eine Form und dann <em>Verbundenes Element hinzufügen</em> (auch im Kontextmenü der Form). Wähle den Verbindungstyp und den Typ des neuen Elements unter denen, die der Viewpoint und das Metamodell vom gewählten Typ aus erlauben. Die neue Form wird rechts von der gewählten platziert, in der Standardlänge des Verbindungstyps: Der Abstand zwischen den beiden Rändern beträgt 90 pt ohne gespeicherte Länge (siehe <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>). Benenne die neue Form wie gewohnt.</li><li><strong>Knickpunkte:</strong> Ein Doppelklick auf eine Kante fügt einen Knickpunkt hinzu, ein Knickpunkt der gewählten Kante wird durch Ziehen verschoben, ein Doppelklick auf einen Knickpunkt entfernt ihn. Eine Kante hat höchstens 50 Knickpunkte.</li><li><strong>Wählen und entfernen:</strong> Erreiche eine Kante mit Tab oder klicke sie an; ihre Details öffnen sich neben der Zeichenfläche (siehe <a href="#details-of-an-entity">Details einer Entität</a>). <em>Aus Diagramm entfernen</em>, Entf oder das Kontextmenü der Kante entfernt nur die Kante; <strong>die Verbindung bleibt im Repository.</strong> Das Entfernen einer Form entfernt ihre Kanten, und eine nur gezeichnete, noch nicht gespeicherte Verbindung verschwindet mit ihrer letzten Kante.</li><li><strong>Grenzen:</strong> Ein Diagramm enthält höchstens 4000 Kanten, und ein Speichern legt höchstens 500 neue Verbindungen an; die Zeichenfläche meldet, wenn eine Grenze erreicht ist.</li></ul><p>Wird eine Verbindung gelöscht, werden ihre Kanten ausgeblendet; sie erscheinen wieder, wenn die Verbindung wiederhergestellt wird. Eine gespeicherte Kante bleibt bestehen, wenn der Viewpoint ihren Verbindungstyp nicht mehr erlaubt, ist dann aber ein Konflikt (siehe <a href="#change-the-viewpoint">Viewpoint ändern</a>); neue Kanten dieses Typs kannst du nicht mehr zeichnen.</p><h2 id="change-the-viewpoint" tabindex="-1">Viewpoint ändern <a class="header-anchor" href="#change-the-viewpoint" aria-label="Permalink to “Viewpoint ändern”">​</a></h2><p>Mit <code>entity:write</code> ändert <em>Viewpoint ändern</em> über der Zeichenfläche den Viewpoint des Diagramms. Die Schaltfläche ist deaktiviert, solange du ungespeicherte Änderungen hast: Speichere oder verwirf sie zuerst. Der Dialog listet die Viewpoints; wählst du einen, nennt er vor der Änderung die Formen und Kanten, deren Typ dieser Viewpoint nicht erlaubt (<em>2 Shapes werden zu Konflikten.</em> oder <em>Es entstehen keine Konflikte.</em>). Die Änderung wird sofort gespeichert, als eigene Änderung; die Formen, Kanten und Linien bleiben, wie sie sind, und die Zeichenfläche lädt mit der Palette und den Standardgrößen des neuen Viewpoints neu. Hat jemand anderes das Diagramm inzwischen geändert, sagt der Dialog das und bietet das Neuladen an.</p><p><strong>Konflikte.</strong> Eine Form oder Kante, deren Typ der Viewpoint des Diagramms nicht erlaubt, ist ein <em>Konflikt</em>. Das geschieht nach einer Änderung des Viewpoints, aber auch, wenn eine Administratorin den Typ aus dem Viewpoint entfernt oder eine neue Version eines <a href="./../administration/metamodel-packages">Metamodell-Pakets</a> es tut. OEA prüft den genauen Typ: Ein Viewpoint, der einen Typ erlaubt, erlaubt nicht dessen Untertypen. Konflikte sind durch einen gestrichelten Rand (oder eine gestrichelte Linie) und den Text <em>Konflikt: Typ in diesem Viewpoint nicht erlaubt</em> markiert, nicht nur durch die Farbe. Die Liste <em>Konflikte (N)</em> über der Zeichenfläche nennt sie; ein Klick auf einen Namen wählt die Form oder Kante aus. Formen einer gelöschten Entität sind ausgeblendet und keine Konflikte, können aber zu Konflikten werden, wenn die Entität wiederhergestellt wird.</p><p><strong>Auflösen.</strong> <em>Aus Diagramm entfernen</em> in der Liste entfernt einen Konflikt mit seinen Kanten und Hierarchielinien (bei einem Container mit verschachtelten Formen fragt OEA vorher, weil die verschachtelten Formen mit ihm das Diagramm verlassen), <em>Alle Konflikte entfernen</em> entfernt alle. Die Entitäten bleiben im Repository. Oder eine Administratorin erlaubt den Typ im Viewpoint wieder; die Markierung verschwindet dann. <strong>Solange ein Konflikt übrig ist, kannst du das Diagramm nicht speichern:</strong> <em>Speichern</em> antwortet <em>Das Diagramm wurde nicht gespeichert: Es hat noch Konflikte</em>, was du sonst auch geändert hast, und behält deine Änderungen. Wer nur lesen darf, sieht die Markierungen und die Liste ohne die Schaltflächen.</p><h2 id="diagramm-umbenennen-und-loschen" tabindex="-1">Diagramm umbenennen und löschen <a class="header-anchor" href="#diagramm-umbenennen-und-loschen" aria-label="Permalink to “Diagramm umbenennen und löschen”">​</a></h2><p><em>Umbenennen</em> ändert Namen und Beschreibung eines Diagramms, auf der Seite <em>Diagramme</em> und auf der Seite des Diagramms. Hat jemand anderes das Diagramm inzwischen geändert, meldet der Dialog das; lade die Seite neu und wiederhole deine Änderung.</p><p><em>Löschen</em> fragt nach einer Bestätigung. Ein gelöschtes Diagramm erscheint nicht mehr in der Liste, im Browser und im Navigationsbaum, und sein Name kann wieder verwendet werden. <strong>Die Entitäten des Repositorys bleiben.</strong> Das Diagramm selbst lässt sich wiederherstellen (siehe unten).</p><h2 id="diagramm-wiederherstellen" tabindex="-1">Diagramm wiederherstellen <a class="header-anchor" href="#diagramm-wiederherstellen" aria-label="Permalink to “Diagramm wiederherstellen”">​</a></h2><p>Mit der Berechtigung <code>entity:restore</code> listet der Schalter <em>Gelöschte anzeigen</em> auf der Seite <em>Diagramme</em> die gelöschten Diagramme mit Zeitpunkt und Person des Löschens. Wähle <em>Wiederherstellen</em>, um ein Diagramm samt seinen Einträgen im Navigationsbaum zurückzuholen. Hat inzwischen ein anderes Diagramm seinen Namen bekommen, meldet die Seite das, und das Diagramm bleibt gelöscht; benenne zuerst das andere Diagramm um.</p><h2 id="viewpoint-loschen" tabindex="-1">Viewpoint löschen <a class="header-anchor" href="#viewpoint-loschen" aria-label="Permalink to “Viewpoint löschen”">​</a></h2><p>Diagramme können ohne ihren Viewpoint nicht bestehen. Löschst du einen Viewpoint, den Diagramme nutzen, werden sie mit ihm <strong>endgültig</strong> gelöscht, auch die bereits gelöschten; die Entitäten bleiben. Die Bestätigung nennt die Anzahl der Diagramme, die gelöscht werden (siehe <a href="./../administration/metamodel-editing#viewpoints">Viewpoints</a>). Dasselbe geschieht, wenn eine neue Version eines <a href="./../administration/metamodel-packages">Metamodell-Pakets</a> einen systemdefinierten Viewpoint nicht mehr enthält.</p><h2 id="through-the-api" tabindex="-1">Über die API <a class="header-anchor" href="#through-the-api" aria-label="Permalink to “Über die API”">​</a></h2><p>Die Diagramme sind über <code>/diagrams</code> verfügbar (siehe die <a href="./../api/">API-Referenz</a>):</p><ul><li><code>GET /diagrams</code> listet die Diagramme nach Namen. <code>q</code> ist ein Namensteil (höchstens 200 Zeichen), <code>pageSize</code> ist 1 bis 200 (Standard 50), und <code>page</code> beginnt bei 0. Die Antwort enthält <code>nextCursor</code>; sende ihn als <code>cursor</code> zusammen mit <code>page</code> um 1 erhöht, um fortzufahren. Ein Cursor einer anderen Abfrage wird mit 400 abgelehnt, das <code>cursor</code> nennt.</li><li><code>POST /diagrams</code> legt ein Diagramm aus <code>name</code>, <code>description</code> und <code>viewpointId</code> an; <code>GET /diagrams/{id}</code> liest es; <code>PUT /diagrams/{id}</code> ändert <code>name</code> und <code>description</code> (eine <code>viewpointId</code> wird ignoriert; <code>PUT /diagrams/{id}/viewpoint</code> ändert den Viewpoint, siehe unten); <code>DELETE /diagrams/{id}</code> löscht es. Jede Änderung braucht den Header <code>If-Match</code> mit der gelesenen Version (<code>&quot;3&quot;</code>); ohne ihn lautet die Antwort 428, mit einer anderen Version 412. Die Antworten tragen die neue Version als <code>ETag</code>.</li><li><code>GET /diagrams/deleted</code> listet die gelöschten Diagramme, und <code>POST /diagrams/{id}/restore</code> mit <code>If-Match</code> stellt eines wieder her; beides braucht <code>entity:restore</code>. Ein Diagramm, das nicht gelöscht ist, antwortet mit 409 (<code>urn:oea:problem:diagram-not-deleted</code>).</li><li>Ein vergebener Name antwortet mit 422 und dem Problemtyp <code>urn:oea:problem:diagram-name-taken</code>; sonstige ungültige Eingaben antworten mit 422 und nennen das Feld in <code>invalidFields</code> (<code>name</code>, <code>description</code> oder <code>viewpointId</code>). Ein unbekanntes oder gelöschtes Diagramm antwortet mit 404.</li><li>Jede Änderung steht im Audit-Trail als <code>diagram.created</code>, <code>diagram.updated</code>, <code>diagram.deleted</code> oder <code>diagram.restored</code>.</li><li><code>PUT /diagrams/{id}/viewpoint</code> mit <code>If-Match</code> und <code>entity:write</code> ändert den Viewpoint auf den in <code>viewpointId</code>; die Änderung wird sofort gespeichert, und die Antwort ist das Diagramm mit <code>conflictCount</code>, der Anzahl der Konflikte. Formen, Kanten und Linien bleiben. Ein unbekannter Viewpoint antwortet mit 422 und nennt <code>viewpointId</code>; der Viewpoint, den das Diagramm schon hat, ändert nichts (keine neue Version, kein Audit). Die Änderung steht als <code>diagram.viewpoint-changed</code> mit <code>fromViewpointId</code>, <code>toViewpointId</code> und <code>conflicts</code> im Audit-Trail.</li><li><code>GET /views/diagrams/{id}</code> markiert jede Form und Kante mit <code>conflict</code> und liefert <code>conflictCount</code>. <code>PUT /views/diagrams/{id}</code> antwortet mit 409 und dem Problemtyp <code>urn:oea:problem:diagram-conflicts</code> sowie <code>invalidFields</code> wie <code>shapes[3]</code> und <code>edges[1]</code>, solange das gespeicherte Layout noch eine Form oder Kante enthält, die ein Konflikt ist, was das Speichern sonst auch ändert (auch ein Speichern ohne Änderung); dann wird nichts geändert. Ein Layoutfehler (422) wird zuerst beantwortet, die fehlende Berechtigung, eine Eigenschaft zu schreiben, nach den Konflikten. Ein Speichern, das alle Konflikte entfernt, wird angenommen; eine neue Form oder Kante eines Typs, den der Viewpoint nicht erlaubt, wird weiterhin mit 422 <code>METATYPE_NOT_ALLOWED</code> abgelehnt.</li><li><code>GET /views/diagrams/{id}</code> liefert die Ansicht eines Diagramms: das Diagramm mit seiner Version (<code>ETag</code>), seinen Viewpoint mit den wirksamen Standardgrößen und die Formen in Zeichenreihenfolge (die letzte liegt oben) mit Form-ID, Entität, Position und Größe in pt sowie <code>missingMandatory</code>, den Namen der Pflichteigenschaften ohne Wert. Formen einer gelöschten Entität fehlen.</li><li><code>PUT /views/diagrams/{id}</code> speichert das Layout mit <code>If-Match</code>: alle <code>shapes</code> in Zeichenreihenfolge (<code>id</code>, genau eines von <code>entityId</code> und <code>newEntityKey</code>, <code>x</code>, <code>y</code>, <code>width</code>, <code>height</code>) und die <code>newEntities</code> (<code>key</code>, <code>metatypeId</code>, <code>name</code>), auf die die Formen mit <code>newEntityKey</code> verweisen. Das Speichern ist atomar und erhöht die Version. Neue Entitäten werden wie Entitäten des Batch-Schreibens angelegt (<code>entity.created</code>), eine Entität mit fehlender Pflichteigenschaft wird aber unvollständig angelegt statt abgelehnt. Grenzen: 2000 Formen, 500 neue Entitäten, Positionen innerhalb von ±100 000 pt, Größen 1 bis 10 000 pt, höchstens zwei Nachkommastellen, ein Body von 4 MB; Verstöße werden mit 400 oder 413 beantwortet. Eine fehlerhafte Form oder neue Entität wird mit 422 samt <code>invalidFields</code> und <code>errors</code> beantwortet (zum Beispiel <code>shapes[3].entityId</code> oder <code>newEntities[1].name</code>); dann wird nichts gespeichert. Auch eine Form-ID eines anderen Diagramms wird abgelehnt.</li><li><code>GET /views/diagrams/{id}/entities</code> durchsucht die Entitäten, die der Viewpoint erlaubt (<code>q</code> bis 255 Zeichen, <code>metatypeId</code>, <code>page</code>, <code>pageSize</code> 1 bis 200); ein Metatyp, den der Viewpoint nicht erlaubt, wird mit 422 und <code>metatypeId</code> beantwortet.</li><li>Jedes gespeicherte Layout steht im Audit-Trail als <code>diagram.layout-saved</code> mit den Anzahlen hinzugefügter, geänderter und entfernter Formen und Kanten, angelegter Entitäten und Verbindungen und der Entitäten, deren Eltern das Speichern geändert hat (<code>parentsChanged</code>).</li><li><code>GET /views/diagrams/{id}/entities/{entityId}</code> liefert die Details einer Entität, die eine Form des Diagramms zeigt: <code>name</code>, <code>description</code>, <code>metatype</code>, <code>version</code>, die Werte in <code>properties</code> (ein Wert, den du nicht lesen darfst, hat <code>redacted: true</code>), in <code>fields</code> für jede zugeordnete Eigenschaft, ob du sie lesen (<code>readable</code>) und ändern (<code>writable</code>) darfst, und <code>missingMandatory</code>. Eine Entität ohne Form im Diagramm, eine gelöschte Entität und ein gelöschtes Diagramm antworten mit 404. Datentypen, Aufzählungswerte und Grenzen der Eigenschaften stammen vom Metatyp (<code>GET /metamodel/metatypes/{id}</code>).</li><li><code>GET /views/diagrams/{id}/reference-targets?propertyDefId=…</code> listet die Entitäten, auf die eine Referenzeigenschaft zeigen darf: die Entitäten genau des referenzierten Typs, nach Namen (<code>q</code> bis 255 Zeichen, <code>page</code>, <code>pageSize</code> 1 bis 200). Eine Eigenschaft, die keine Referenzeigenschaft ist, antwortet mit 422 und nennt <code>propertyDefId</code>.</li><li><code>PUT /views/diagrams/{id}</code> trägt auch <code>entityUpdates</code>, höchstens 500: Jede nennt eine <code>entityId</code>, die eine Form derselben Anfrage zeigt (einmal), die gelesene <code>expectedVersion</code> (mindestens 1) und optional <code>name</code> (nicht leer, bis 255 Zeichen), <code>description</code> (bis 2000) und <code>properties</code> (<code>propertyDefId</code> und <code>value</code>; ein leerer <code>value</code> entfernt den Wert). Nicht genannte Felder und Eigenschaften behalten ihren Wert. Die Änderungen werden in derselben Transaktion wie das Layout geschrieben, mit den Prüfungen und dem Audit einer Batch-Änderung (<code>entity.updated</code>); eine geänderte Entität braucht ihre Pflichtwerte (422 <code>MANDATORY_MISSING</code> auf <code>entityUpdates[i].properties</code>), und eine eingeschränkte Eigenschaft ohne Schreibzugriff führt für das ganze Speichern zu 403. Ein Eintrag von <code>newEntities</code> kann ebenfalls <code>description</code> und <code>properties</code> tragen. Eine Entität mit anderer aktueller Version antwortet mit 409 und dem Problemtyp <code>urn:oea:problem:entity-version-conflict</code> samt <code>conflicts</code> (<code>entityId</code> und <code>currentVersion</code> jeder veralteten Entität); eine Entität mit einem offenen Punkt einer Lösung antwortet mit 409 <code>urn:oea:problem:entity-blocked</code>. Es wird dann nichts geändert. Die Batch-API (<code>POST /entities/batch</code>) schreibt weiterhin ohne Version.</li><li><code>GET /views/diagrams/{id}</code> liefert zusätzlich die <code>edges</code>: jede mit der Kanten-ID, der <code>connection</code> (<code>id</code>, <code>name</code>, <code>metatypeId</code>), <code>sourceShapeId</code> und <code>targetShapeId</code>, den Knickpunkten <code>points</code> in pt und <code>missingMandatory</code>. Kanten einer gelöschten Verbindung oder einer Form einer gelöschten Entität bleiben weg.</li><li><code>PUT /views/diagrams/{id}</code> trägt zusätzlich <code>edges</code> (höchstens 4000; die gespeicherte Menge ersetzt die vorhandene) und <code>newConnections</code> (höchstens 500). Eine Kante hat eine ID, genau eines von <code>connectionId</code> und <code>newConnectionKey</code>, <code>sourceShapeId</code> und <code>targetShapeId</code> von Formen derselben Anfrage und <code>points</code> (höchstens 50, jeder innerhalb von ±100 000 pt mit höchstens zwei Nachkommastellen). Die Quellform muss die Quellentität der Verbindung zeigen und die Zielform ihre Zielentität; eine neue Kante braucht einen Verbindungstyp, den der Viewpoint erlaubt. Ein Eintrag von <code>newConnections</code> hat <code>key</code>, <code>metatypeId</code> und optional <code>name</code>, <code>description</code> und <code>properties</code>; seine Enden sind die Entitäten der Formen seiner ersten Kante, und er braucht mindestens eine Kante. Neue Verbindungen werden nach den neuen Entitäten mit den Prüfungen und dem Audit einer Verbindung des Batch-Schreibens angelegt (<code>entity.created</code>; die Codes <code>SOURCE_NOT_ALLOWED</code> und <code>TARGET_NOT_ALLOWED</code> nennen <code>newConnections[i]</code>), ein fehlender Pflichtwert blockiert sie nicht, und eine Verbindung eines Scoping-Typs braucht <code>visibility-scope:assign</code> (403 für das ganze Speichern, vor der Versionsprüfung). Eine fehlerhafte Kante oder neue Verbindung wird mit 422 beantwortet und nennt <code>edges[i]</code> oder <code>newConnections[i]</code>; mehr als 4000 Kanten, 50 Knickpunkte an einer Kante oder 500 neue Verbindungen führen zu 400. <code>entityUpdates</code> darf eine Verbindung nennen, die eine Kante der Anfrage zeigt. Der Body ist auf 4 MB begrenzt. <code>diagram.layout-saved</code> trägt zusätzlich <code>edgesAdded</code>, <code>edgesChanged</code>, <code>edgesRemoved</code> und <code>connectionsCreated</code>.</li><li><code>GET /views/diagrams/{id}/entities/{entityId}</code> antwortet auch für eine Verbindung, die eine Kante des Diagramms zeigt; eine Verbindung ohne Kante oder mit ausgeblendeter Kante antwortet mit 404.</li><li><code>GET /entities/{id}/deletion</code> zeigt eine Vorschau von „Aus Repository löschen“ (<code>entity:delete</code>): die Entität mit ihrer Version, die Zahl ihrer Kinder und der mitgelöschten Verbindungen und die aktiven Lösungen mit der Zahl ihrer Änderungen. <code>DELETE /entities/{id}</code> mit <code>If-Match</code> löscht die Entität, ihre Kinder auf allen Ebenen und deren Verbindungen mit einer Zeit und einem Akteur und antwortet mit den IDs von allem Gelöschten; eine Verbindung wird allein gelöscht. Offene Punkte antworten 409 <code>entity-blocked</code>, eine Gliederungshilfe oder eine automatische Kompositionsverbindung 422, eine Verbindung eines Scoping-Typs ohne <code>visibility-scope:assign</code> 403. <code>POST /entities/{id}/undelete</code> mit <code>If-Match</code> stellt die Entität mit genau ihrer Kaskade wieder her (<code>entity:restore</code>) und nennt die Verbindungen, die gelöscht bleiben, weil ihr anderer Endpunkt noch gelöscht ist; eine Entität, die nicht gelöscht ist, antwortet 409 <code>entity-not-deleted</code>. Die Ereignisse sind <code>entity.deleted</code>, <code>entity.cascade-deleted</code> und <code>entity.undeleted</code>.</li><li><code>POST /views/diagrams/{id}/connections/query</code> mit <code>entityIds</code> (1 bis 2000 gerade platzierte Entitäten) und <code>shownEntityIds</code> (0 bis 2000 weitere gezeigte Entitäten) liefert die nicht gelöschten Verbindungen erlaubter Typen, die eine platzierte Entität mit einer platzierten oder gezeigten verbinden, nach ID, höchstens 5000, mit <code>truncated</code> bei mehr (<code>entity:read</code>; es liest nur und wird nicht auditiert).</li><li><code>GET /views/diagrams/{id}</code> liefert zusätzlich <code>parentShapeId</code> an jeder Form (der Container; <code>null</code> für eine Form auf der Zeichenfläche, auch wenn der Container ausgeblendet ist, später in der Zeichenreihenfolge kommt oder die Form nicht mehr enthält), <code>childCount</code> und <code>parentEntityId</code> an ihrer Entität, die <code>hierarchyLines</code> (<code>id</code>, <code>parentShapeId</code>, <code>childShapeId</code>; nur die, deren Hierarchie gilt) und die wirksame Einstellung <code>askNewParent</code>.</li><li><code>PUT /views/diagrams/{id}</code> trägt zusätzlich <code>parentShapeId</code> je Form (eine Form derselben Anfrage weiter vorn in der Liste, höchstens 10 Ebenen tief, ohne Zyklus, die die Form vollständig enthält; Positionen bleiben absolut), <code>hierarchyLines</code> (höchstens 4000, jedes Formenpaar einmal, und die Entität der Kind-Form muss nach den Elternänderungen desselben Speicherns ein Kind der Entität der Container-Form sein) und <code>parentChanges</code> (höchstens 500; jede nennt eine <code>entityId</code>, die eine Form der Anfrage zeigt, einmal, die <code>expectedVersion</code> und höchstens eines von <code>parentEntityId</code> und <code>parentNewEntityKey</code>; keines löscht die Eltern). Ein Eintrag von <code>newEntities</code> kann <code>parentEntityId</code> oder <code>parentNewEntityKey</code> tragen und endet dann bei Version 2. Die Eltern werden in der Transaktion des Speicherns mit den Regeln, der automatischen Kompositionsverbindung und dem Audit <code>entity.parent-changed</code> von <code>PUT /entities/{id}/parent</code> geschrieben; eine Änderung auf die aktuellen Eltern schreibt nichts. Eine veraltete Version antwortet 409 <code>entity-version-conflict</code> (<code>invalidFields</code> nennt <code>parentChanges[i]</code>), ein offenes Problem 409 <code>entity-blocked</code>. Ein fehlerhafter Container, eine fehlerhafte Linie oder fehlerhafte Eltern antworten 422 mit <code>shapes[i].parentShapeId</code>, <code>hierarchyLines[i]</code>, <code>parentChanges[i]</code> oder <code>newEntities[i].parentEntityId</code>; mehr als 4000 Linien oder 500 Elternänderungen antworten 400.</li><li><code>GET /views/diagrams/{id}/entities/{entityId}/children</code> listet die direkten Kinder einer Entität, die nicht gelöscht sind, nach Name (höchstens 500, <code>truncated</code> für mehr), je mit <code>allowed</code> (der Viewpoint erlaubt ihren Typ) und ihrer Kompositionsverbindung (<code>compositionConnection</code>, mit <code>allowed</code> für ihren Typ). Eine unbekannte, gelöschte oder Verbindungs-Entität antwortet 404 (<code>entity:read</code>; liest nur und wird nicht auditiert).</li></ul>`,46)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};